CREATE TABLE InventoryImport (id VARCHAR(191) NOT NULL PRIMARY KEY,shopId VARCHAR(191) NOT NULL,actorId VARCHAR(191) NOT NULL,fileHash VARCHAR(191) NOT NULL,state VARCHAR(191) NOT NULL DEFAULT 'PREVIEW',total INTEGER NOT NULL,invalid INTEGER NOT NULL,snapshot JSON NOT NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),expiresAt DATETIME(3) NOT NULL,committedAt DATETIME(3) NULL,INDEX InventoryImport_shopId_createdAt_idx(shopId,createdAt)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
